import { S3Client, GetObjectCommand, PutObjectCommand } from '@aws-sdk/client-s3';
import sharp from 'sharp';

const s3 = new S3Client({});

export const handler = async (event) => {
  const record = event.Records[0].s3;
  const bucket = record.bucket.name;
  const key = decodeURIComponent(record.object.key.replace(/\+/g, ' '));

  // Skip files that are already thumbnails, avoid triggering ourselves in a loop
  if (key.startsWith('thumbnails/')) {
    return { statusCode: 200, body: 'Skipped, already a thumbnail' };
  }

  const original = await s3.send(new GetObjectCommand({ Bucket: bucket, Key: key }));
  const buffer = await streamToBuffer(original.Body);

  const thumbnail = await sharp(buffer)
    .resize(200, 200, { fit: 'cover' })
    .jpeg({ quality: 80 })
    .toBuffer();

  const thumbKey = key.replace('uploads/', 'thumbnails/');

  await s3.send(new PutObjectCommand({
    Bucket: bucket,
    Key: thumbKey,
    Body: thumbnail,
    ContentType: 'image/jpeg'
  }));

  return { statusCode: 200, body: `Thumbnail written to ${thumbKey}` };
};

function streamToBuffer(stream) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    stream.on('data', (chunk) => chunks.push(chunk));
    stream.on('error', reject);
    stream.on('end', () => resolve(Buffer.concat(chunks)));
  });
}

